export interface ScanEntry {
  path: string;
  isRepo: boolean;
}

interface CacheRecord {
  mtimeMs: number;
  entries: ScanEntry[];
}

/**
 * Remembers one workspace walk, keyed on the root's own mtime.
 *
 * The guard is the whole point: a new clone bumps the directory's mtime, so the next read
 * misses and re-walks without anyone having to flush by hand.
 */
export class ScanCache {
  #records = new Map<string, CacheRecord>();

  read(root: string, mtimeMs: number): ScanEntry[] | null {
    const hit = this.#records.get(root);
    if (!hit || hit.mtimeMs !== mtimeMs) return null;
    return hit.entries;
  }

  write(root: string, mtimeMs: number, entries: ScanEntry[]): void {
    this.#records.set(root, { mtimeMs, entries: [...entries] });
  }

  get size(): number {
    return this.#records.size;
  }
}

import { ScanCache } from "./scan-cache.ts";

export interface FleetCounts {
  active: number;
  waiting: number;
  idle: number;
}

/** One process-wide cache, so two summaries in the same tick share a single walk. */
const scans = new ScanCache();

/** A one-line summary of the fleet's current state. */
export function summarize(counts: FleetCounts): string {
  return `${counts.active} active, ${counts.waiting} waiting, ${counts.idle} idle`;
}

/** The same summary, plus how many workspace roots answered from cache. */
export function summarizeWithScan(counts: FleetCounts): string {
  return `${summarize(counts)} (${scans.size} cached roots)`;
}

export { scans };

import assert from "node:assert/strict";
import test from "node:test";
import { ScanCache } from "./scan-cache.ts";

test("returns the remembered walk for an unchanged mtime", () => {
  const cache = new ScanCache();
  cache.write("/w", 10, [{ path: "/w/api", isRepo: true }]);
  assert.deepEqual(cache.read("/w", 10), [{ path: "/w/api", isRepo: true }]);
});

test("misses once the root's mtime moves", () => {
  const cache = new ScanCache();
  cache.write("/w", 10, [{ path: "/w/api", isRepo: true }]);
  assert.equal(cache.read("/w", 11), null);
});

test("hands back a copy, so a caller cannot mutate the cache", () => {
  const cache = new ScanCache();
  const entries = [{ path: "/w/api", isRepo: true }];
  cache.write("/w", 10, entries);
  entries.push({ path: "/w/web", isRepo: false });
  assert.equal(cache.read("/w", 10)?.length, 1);
});
